// FreeLang GPT: Phase 1 - Tensor Operations
// ==================================================
// Core tensor computation module
// Status: 🟢 Implementation (Phase 1 Pilot)
// Tests: 20/20 target

module tensor

import math
import arrays

// ==================================================
// 1. TENSOR RECORD & METADATA
// ==================================================

// Tensor: N-dimensional array with shape and strides
record Tensor {
  data: Array[Float],    // 1D flattened data
  shape: Array[Int],     // dimensions [rows, cols, ...]
  strides: Array[Int],   // C-contiguous: [cols, 1] for 2D
  ndim: Int,             // number of dimensions
  size: Int              // total elements
}

// ==================================================
// 2. TENSOR CREATION
// ==================================================

// Create zero tensor
function zeros_tensor(shape: Array[Int]) -> Tensor = {
  let total_size = fold(shape, 1, fn(acc, dim) -> acc * dim)
  let data = fold_range(0, total_size, [], fn(acc, _) -> {
    append(acc, 0.0)
  })
  let strides = compute_strides(shape)

  Tensor {
    data: data,
    shape: shape,
    strides: strides,
    ndim: len(shape),
    size: total_size
  }
}

// Create ones tensor
function ones_tensor(shape: Array[Int]) -> Tensor = {
  let total_size = fold(shape, 1, fn(acc, dim) -> acc * dim)
  let data = fold_range(0, total_size, [], fn(acc, _) -> {
    append(acc, 1.0)
  })
  let strides = compute_strides(shape)

  Tensor {
    data: data,
    shape: shape,
    strides: strides,
    ndim: len(shape),
    size: total_size
  }
}

// Create random normal tensor (simplified: uniform [0,1] for now)
function randn_tensor(shape: Array[Int], seed: Int) -> Tensor = {
  let total_size = fold(shape, 1, fn(acc, dim) -> acc * dim)
  let data = fold_range(0, total_size, [], fn(acc, i) -> {
    let val = as_float((seed + i) % 100) / 100.0
    append(acc, val)
  })
  let strides = compute_strides(shape)

  Tensor {
    data: data,
    shape: shape,
    strides: strides,
    ndim: len(shape),
    size: total_size
  }
}

// ==================================================
// 3. STRIDE COMPUTATION (C-CONTIGUOUS)
// ==================================================

// Compute strides for C-contiguous layout
// Example: shape=[3,4] -> strides=[4,1]
function compute_strides(shape: Array[Int]) -> Array[Int] = {
  if len(shape) == 0 {
    []
  } else if len(shape) == 1 {
    [1]
  } else {
    let strides = []
    let stride = 1
    let rev_shape = reverse(shape)

    let result = fold(rev_shape, [], fn(acc, dim) -> {
      let new_stride = stride * dim
      append(acc, stride)
    })

    reverse(result)
  }
}

// Helper: reverse array
function reverse(arr: Array[Int]) -> Array[Int] = {
  let result = []
  fold_range(0, len(arr), result, fn(acc, i) -> {
    let idx = len(arr) - 1 - i
    append(acc, arr[idx])
  })
}

// ==================================================
// 4. TENSOR INDEXING (2D HELPER FUNCTIONS)
// ==================================================

// Convert 2D indices to 1D flat index
function tensor_index_2d(t: Tensor, i: Int, j: Int) -> Int = {
  i * t.shape[1] + j
}

// Get element at 2D position
function tensor_get_2d(t: Tensor, i: Int, j: Int) -> Float = {
  let idx = tensor_index_2d(t, i, j)
  t.data[idx]
}

// Set element at 2D position (returns new tensor)
function tensor_set_2d(mutable t: Tensor, i: Int, j: Int, val: Float) -> Void = {
  let idx = tensor_index_2d(t, i, j)
  t.data[idx] = val
}

// ==================================================
// 5. TENSOR OPERATIONS
// ==================================================

// Element-wise addition
function tensor_add(a: Tensor, b: Tensor) -> Tensor = {
  let result_data = []
  let result = fold_range(0, a.size, result_data, fn(acc, i) -> {
    append(acc, a.data[i] + b.data[i])
  })

  Tensor {
    data: result,
    shape: a.shape,
    strides: a.strides,
    ndim: a.ndim,
    size: a.size
  }
}

// Element-wise scalar multiplication
function tensor_scale(t: Tensor, scalar: Float) -> Tensor = {
  let result_data = []
  let result = fold_range(0, t.size, result_data, fn(acc, i) -> {
    append(acc, t.data[i] * scalar)
  })

  Tensor {
    data: result,
    shape: t.shape,
    strides: t.strides,
    ndim: t.ndim,
    size: t.size
  }
}

// Element-wise multiplication
function tensor_mul(a: Tensor, b: Tensor) -> Tensor = {
  let result_data = []
  let result = fold_range(0, a.size, result_data, fn(acc, i) -> {
    append(acc, a.data[i] * b.data[i])
  })

  Tensor {
    data: result,
    shape: a.shape,
    strides: a.strides,
    ndim: a.ndim,
    size: a.size
  }
}

// ==================================================
// 6. MATRIX MULTIPLICATION (2D ONLY)
// ==================================================

// Matrix multiplication: (m x n) @ (n x k) -> (m x k)
function matmul_2d(a: Tensor, b: Tensor) -> Tensor = {
  let m = a.shape[0]
  let n = a.shape[1]
  let k = b.shape[1]

  let result = zeros_tensor([m, k])

  // Nested loops: result[i,j] = sum(a[i,:] * b[:,j])
  fold_range(0, m, result, fn(res, i) -> {
    fold_range(0, k, res, fn(res2, j) -> {
      // Compute dot product: a[i,:] . b[:,j]
      let dot_product = fold_range(0, n, 0.0, fn(acc, p) -> {
        let a_val = tensor_get_2d(a, i, p)
        let b_val = tensor_get_2d(b, p, j)
        acc + (a_val * b_val)
      })

      tensor_set_2d(res2, i, j, dot_product)
      res2
    })
  })
}

// ==================================================
// 7. UTILITY FUNCTIONS
// ==================================================

// Get tensor shape
function tensor_shape(t: Tensor) -> Array[Int] = t.shape

// Get tensor total size
function tensor_size(t: Tensor) -> Int = t.size

// Get element count for dimension
function tensor_dim(t: Tensor, d: Int) -> Int = {
  if d >= 0 && d < len(t.shape) {
    t.shape[d]
  } else {
    0
  }
}

// ==================================================
// 8. TESTS
// ==================================================

function test_zeros_ones() -> Bool = {
  let z = zeros_tensor([2, 3])
  let o = ones_tensor([2, 3])

  // Check zeros
  let z_check = tensor_get_2d(z, 0, 0) == 0.0

  // Check ones
  let o_check = tensor_get_2d(o, 0, 0) == 1.0

  z_check && o_check
}

function test_tensor_indexing() -> Bool = {
  let t = zeros_tensor([3, 3])
  tensor_set_2d(t, 1, 2, 5.5)
  let val = tensor_get_2d(t, 1, 2)
  val == 5.5
}

function test_tensor_add() -> Bool = {
  let a = ones_tensor([2, 2])
  let b = ones_tensor([2, 2])
  let c = tensor_add(a, b)

  let check = tensor_get_2d(c, 0, 0) == 2.0
  check
}

function test_tensor_scale() -> Bool = {
  let t = ones_tensor([2, 2])
  let scaled = tensor_scale(t, 3.0)

  let val = tensor_get_2d(scaled, 0, 0)
  val == 3.0
}

function test_matmul_2x2() -> Bool = {
  // A = [[1, 2], [3, 4]]
  let a = zeros_tensor([2, 2])
  tensor_set_2d(a, 0, 0, 1.0)
  tensor_set_2d(a, 0, 1, 2.0)
  tensor_set_2d(a, 1, 0, 3.0)
  tensor_set_2d(a, 1, 1, 4.0)

  // B = [[5, 6], [7, 8]]
  let b = zeros_tensor([2, 2])
  tensor_set_2d(b, 0, 0, 5.0)
  tensor_set_2d(b, 0, 1, 6.0)
  tensor_set_2d(b, 1, 0, 7.0)
  tensor_set_2d(b, 1, 1, 8.0)

  // C = A @ B = [[19, 22], [43, 50]]
  let c = matmul_2d(a, b)

  let c00 = tensor_get_2d(c, 0, 0)  // 1*5 + 2*7 = 19
  let c01 = tensor_get_2d(c, 0, 1)  // 1*6 + 2*8 = 22
  let c10 = tensor_get_2d(c, 1, 0)  // 3*5 + 4*7 = 43
  let c11 = tensor_get_2d(c, 1, 1)  // 3*6 + 4*8 = 50

  c00 == 19.0 && c01 == 22.0 && c10 == 43.0 && c11 == 50.0
}

function test_matmul_3x3() -> Bool = {
  // Identity matrix
  let i = zeros_tensor([3, 3])
  tensor_set_2d(i, 0, 0, 1.0)
  tensor_set_2d(i, 1, 1, 1.0)
  tensor_set_2d(i, 2, 2, 1.0)

  // A = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
  let a = zeros_tensor([3, 3])
  let idx = 1
  fold_range(0, 3, idx, fn(acc, i) -> {
    fold_range(0, 3, acc, fn(acc2, j) -> {
      tensor_set_2d(a, i, j, as_float(acc2))
      acc2 + 1
    })
  })

  // I @ A = A
  let result = matmul_2d(i, a)

  let a00 = tensor_get_2d(a, 0, 0)
  let r00 = tensor_get_2d(result, 0, 0)

  r00 == a00
}

function test_tensor_shape() -> Bool = {
  let t = zeros_tensor([5, 3])
  let shape = tensor_shape(t)

  len(shape) == 2 && shape[0] == 5 && shape[1] == 3
}

function test_tensor_size() -> Bool = {
  let t = zeros_tensor([4, 5])
  tensor_size(t) == 20
}

function test_tensor_mul() -> Bool = {
  let a = ones_tensor([2, 2])
  let b = ones_tensor([2, 2])
  let c = tensor_mul(a, b)

  let val = tensor_get_2d(c, 0, 0)
  val == 1.0
}

// Run all tests
function run_all_tests() -> Bool = {
  let t1 = test_zeros_ones()
  let t2 = test_tensor_indexing()
  let t3 = test_tensor_add()
  let t4 = test_tensor_scale()
  let t5 = test_matmul_2x2()
  let t6 = test_matmul_3x3()
  let t7 = test_tensor_shape()
  let t8 = test_tensor_size()
  let t9 = test_tensor_mul()

  t1 && t2 && t3 && t4 && t5 && t6 && t7 && t8 && t9
}

// ==================================================
// END OF TENSOR MODULE
// ==================================================

