// FreeLang GPT: tensor.fl → tensor.fl8
// tensor.fl (원본 문법) → fl8 문법으로 포팅
// 내장 bulitin: zeros, ones, randn, matmul, len, range, push

print("=== Tensor Module (tensor.fl8) ===")

// ──────────────────────────────────────────────────────────
// 1. Tensor 생성
// ──────────────────────────────────────────────────────────

// zeros_tensor([rows, cols]) -> { data, shape }
fn make_zeros(rows, cols) {
  let t = zeros(rows, cols)
  return t
}

fn make_ones(rows, cols) {
  let t = ones(rows, cols)
  return t
}

fn make_randn(rows, cols) {
  let t = randn(rows, cols)
  return t
}

// ──────────────────────────────────────────────────────────
// 2. 2D 인덱싱
// ──────────────────────────────────────────────────────────

fn tensor_get(t, i, j) {
  let cols = t.shape[1]
  let idx = i * cols + j
  return t.data[idx]
}

fn tensor_set(t, i, j, val) {
  let cols = t.shape[1]
  let idx = i * cols + j
  t.data[idx] = val
}

// ──────────────────────────────────────────────────────────
// 3. Element-wise 연산
// ──────────────────────────────────────────────────────────

fn tensor_add(a, b) {
  let size = len(a.data)
  let result_data = []
  let i = 0
  while i < size {
    push(result_data, a.data[i] + b.data[i])
    i = i + 1
  }
  return tensor(result_data, a.shape)
}

fn tensor_mul(a, b) {
  let size = len(a.data)
  let result_data = []
  let i = 0
  while i < size {
    push(result_data, a.data[i] * b.data[i])
    i = i + 1
  }
  return tensor(result_data, a.shape)
}

fn tensor_scale(t, scalar) {
  let size = len(t.data)
  let result_data = []
  let i = 0
  while i < size {
    push(result_data, t.data[i] * scalar)
    i = i + 1
  }
  return tensor(result_data, t.shape)
}

// ──────────────────────────────────────────────────────────
// 4. 행렬 곱 (내장 matmul 사용)
// ──────────────────────────────────────────────────────────

fn matmul_2d(a, b) {
  return matmul(a, b)
}

// ──────────────────────────────────────────────────────────
// 5. 유틸
// ──────────────────────────────────────────────────────────

fn tensor_size(t) {
  let s = 1
  let i = 0
  while i < len(t.shape) {
    s = s * t.shape[i]
    i = i + 1
  }
  return s
}

fn tensor_dim(t, d) {
  return t.shape[d]
}

// ──────────────────────────────────────────────────────────
// 6. 테스트
// ──────────────────────────────────────────────────────────

print("--- test: zeros / ones ---")
let z = make_zeros(2, 3)
let o = make_ones(2, 3)
print("zeros[0,0]:", tensor_get(z, 0, 0))  // 0
print("ones[0,0]:",  tensor_get(o, 0, 0))  // 1

print("--- test: tensor_set / tensor_get ---")
let t = make_zeros(3, 3)
tensor_set(t, 1, 2, 5.5)
print("t[1,2]:", tensor_get(t, 1, 2))  // 5.5

print("--- test: tensor_add ---")
let a = make_ones(2, 2)
let b = make_ones(2, 2)
