// FreeLang GPT: tensor.fl → tensor.fl8
// tensor.fl (원본 문법) → fl8 문법으로 포팅

print("=== Tensor Module (tensor.fl8) ===")

// ──────────────────────────────────────────────────────────
// 1. Tensor 생성
// ──────────────────────────────────────────────────────────

fn make_zeros(rows: i64, cols: i64) -> any {
  return zeros(rows, cols)
}

fn make_ones(rows: i64, cols: i64) -> any {
  return ones(rows, cols)
}

fn make_randn(rows: i64, cols: i64) -> any {
  return randn(rows, cols)
}

// ──────────────────────────────────────────────────────────
// 2. 2D 인덱싱
// ──────────────────────────────────────────────────────────

fn tensor_get(t: any, i: i64, j: i64) -> any {
  let cols = t.shape[1]
  let idx = i * cols + j
  return t.data[idx]
}

fn tensor_set(t: any, i: i64, j: i64, val: f64) -> any {
  let cols = t.shape[1]
  let idx = i * cols + j
  t.data[idx] = val
}

// ──────────────────────────────────────────────────────────
// 3. Element-wise 연산
// ──────────────────────────────────────────────────────────

fn tensor_add(a: any, b: any) -> any {
  let size = len(a.data)
  let result_data = []
  let i = 0
  while i < size {
    push(result_data, a.data[i] + b.data[i])
    i = i + 1
  }
  return tensor(result_data, a.shape)
}

fn tensor_mul(a: any, b: any) -> any {
  let size = len(a.data)
  let result_data = []
  let i = 0
  while i < size {
    push(result_data, a.data[i] * b.data[i])
    i = i + 1
  }
  return tensor(result_data, a.shape)
}

fn tensor_scale(t: any, scalar: f64) -> any {
  let size = len(t.data)
  let result_data = []
  let i = 0
  while i < size {
    push(result_data, t.data[i] * scalar)
    i = i + 1
  }
  return tensor(result_data, t.shape)
}

// ──────────────────────────────────────────────────────────
// 4. 행렬 곱
// ──────────────────────────────────────────────────────────

fn matmul_2d(a: any, b: any) -> any {
  return matmul(a, b)
}

// ──────────────────────────────────────────────────────────
// 5. 유틸
// ──────────────────────────────────────────────────────────

fn tensor_size(t: any) -> i64 {
  let s = 1
  let i = 0
  while i < len(t.shape) {
    s = s * t.shape[i]
    i = i + 1
  }
  return s
}

fn tensor_dim(t: any, d: i64) -> i64 {
  return t.shape[d]
}

