let b2 = val(3.0)
let z2 = val_mul(a2, b2)
val_backward(z2)
print("a.grad:", val_grad(a2))  // 3.0
print("b.grad:", val_grad(b2))  // 2.0

print("--- test: chain rule (add + mul) ---")
// z = (a + b) * c
// dz/da = c = 4, dz/db = c = 4, dz/dc = a+b = 5
let a3 = val(2.0)
let b3 = val(3.0)
let c3 = val(4.0)
let ab = val_add(a3, b3)
let z3 = val_mul(ab, c3)
val_backward(z3)
print("a.grad:", val_grad(a3))  // 4.0
print("b.grad:", val_grad(b3))  // 4.0
print("c.grad:", val_grad(c3))  // 5.0

print("--- test: relu backward ---")
// relu(x) = max(0, x), d/dx = 1 if x>0 else 0
let x_pos = val(2.0)
let x_neg = val(-3.0)
let r_pos = val_relu(x_pos)
let r_neg = val_relu(x_neg)
val_backward(r_pos)
val_backward(r_neg)
print("relu(2).grad:",  val_grad(x_pos))  // 1.0
print("relu(-3).grad:", val_grad(x_neg))  // 0.0

print("--- test: tanh backward ---")
// tanh(0) = 0, d/dx = 1 - tanh(x)^2 = 1.0 at x=0
let x_tanh = val(0.0)
let y_tanh = val_tanh(x_tanh)
val_backward(y_tanh)
print("tanh(0).grad:", val_grad(x_tanh))  // 1.0

print("--- test: pow backward ---")
// z = x^3, dz/dx = 3*x^2 = 3*4 = 12 at x=2
let x_pow = val(2.0)
let z_pow = val_pow(x_pow, 3.0)
val_backward(z_pow)
print("x^3 at x=2, grad:", val_grad(x_pow))  // 12.0

// ──────────────────────────────────────────────────────────
// 2. 간단한 MSE 손실 역전파
// ──────────────────────────────────────────────────────────

print("--- test: MSE loss backward ---")
// pred=1.0, target=0.0, loss = (pred - target)^2 = 1.0
// d_loss/d_pred = 2*(pred - target) = 2.0
let pred = val(1.0)
let target = val(0.0)
let diff = val_add(pred, val_mul(target, val(-1.0)))  // pred - target
let loss = val_pow(diff, 2.0)
val_backward(loss)
print("pred.grad:", val_grad(pred))    // 2.0

// ──────────────────────────────────────────────────────────
// 3. 2층 네트워크 forward+backward (스칼라)
// ──────────────────────────────────────────────────────────

print("--- test: 2-layer net (scalar) ---")
// w1=0.5, w2=0.5, x=1.0
// h = tanh(w1 * x), y = w2 * h
// dy/dw1 = w2 * (1 - h^2) * x
let w1 = val(0.5)
let w2 = val(0.5)
let x  = val(1.0)

let pre_h = val_mul(w1, x)
let h     = val_tanh(pre_h)
let y     = val_mul(w2, h)

val_backward(y)

let h_val   = val_data(h)
let dydw1_expected = 0.5 * (1.0 - h_val * h_val) * 1.0
print("w1.grad:", val_grad(w1))
print("w2.grad:", val_grad(w2))
print("expected w1.grad ~", dydw1_expected)

print("=== 모든 autograd 테스트 완료 ===")

