// FreeLang GPT: nn.fl → nn.fl8
// Linear / LayerNorm: 내장 사용
// relu / gelu / softmax / transpose: fl8로 구현

print("=== NN Module (nn.fl8) ===")

// ──────────────────────────────────────────────────────────
// 1. Activation functions
// ──────────────────────────────────────────────────────────

fn relu_t(t: any) -> any {
  let size = len(t.data)
  let out = []
  let i = 0
  while i < size {
    let v = t.data[i]
    if v > 0.0 {
      push(out, v)
    } else {
      push(out, 0.0)
    }
    i = i + 1
  }
  return tensor(out, t.shape)
}

fn gelu_t(t: any) -> any {
  let cdf_coeff = 0.7978845608028654
  let cubic_coeff = 0.044715
  let size = len(t.data)
  let out = []
  let i = 0
  while i < size {
    let v = t.data[i]
    let inner = cdf_coeff * (v + cubic_coeff * v * v * v)
    let cdf = 0.5 * (1.0 + tanh(inner))
    push(out, v * cdf)
    i = i + 1
  }
  return tensor(out, t.shape)
}

fn softmax_2d(t: any) -> any {
  let rows = t.shape[0]
  let cols = t.shape[1]
  let out = zeros(rows, cols)
  let i = 0
  while i < rows {
    // find max
    let max_v = tget(t, i, 0)
    let k = 1
    while k < cols {
      let v = tget(t, i, k)
      if v > max_v {
        max_v = v
      }
      k = k + 1
    }
    // exp sum
    let sum_e = 0.0
    let j = 0
    while j < cols {
      let e = exp(tget(t, i, j) - max_v)
      tset(out, i, j, e)
      sum_e = sum_e + e
      j = j + 1
    }
    // normalize
    let j2 = 0
    while j2 < cols {
      tset(out, i, j2, tget(out, i, j2) / sum_e)
      j2 = j2 + 1
    }
    i = i + 1
  }
  return out
}

fn transpose_2d(t: any) -> any {
  let rows = t.shape[0]
  let cols = t.shape[1]
  let out = zeros(cols, rows)
  let i = 0
  while i < rows {
    let j = 0
    while j < cols {
      tset(out, j, i, tget(t, i, j))
      j = j + 1
    }
    i = i + 1
  }
  return out
}

// ──────────────────────────────────────────────────────────
// 2. Linear layer (내장 Linear + 수동 forward)
// ──────────────────────────────────────────────────────────

fn linear_forward(w: any, b: any, x: any) -> any {
  // y = x @ W^T + b
  let wt = transpose(w)
  let out = matmul(x, wt)
  // bias broadcast
  let rows = out.shape[0]
  let cols = out.shape[1]
  let i = 0
  while i < rows {
    let j = 0
    while j < cols {
      tset(out, i, j, tget(out, i, j) + b.data[j])
      j = j + 1
    }
    i = i + 1
  }
  return out
}

// ──────────────────────────────────────────────────────────
// 3. LayerNorm (수동 구현)
// ──────────────────────────────────────────────────────────

fn layer_norm(x: any, gamma: any, beta: any, eps: f64) -> any {
  let rows = x.shape[0]
  let cols = x.shape[1]
  let out = zeros(rows, cols)
  let i = 0
  while i < rows {
    // mean
    let sum = 0.0
    let j = 0
    while j < cols {
      sum = sum + tget(x, i, j)
      j = j + 1
    }
    let mean = sum / cols
    // variance
    let var_sum = 0.0
    let j2 = 0
    while j2 < cols {
      let d = tget(x, i, j2) - mean
      var_sum = var_sum + d * d
      j2 = j2 + 1
    }
    let std = sqrt(var_sum / cols + eps)
    // normalize + scale + shift
    let j3 = 0
    while j3 < cols {
      let norm = (tget(x, i, j3) - mean) / std
      tset(out, i, j3, norm * gamma.data[j3] + beta.data[j3])
      j3 = j3 + 1
    }
    i = i + 1
  }
  return out
}

// ──────────────────────────────────────────────────────────
// 4. 테스트
// ──────────────────────────────────────────────────────────

print("--- test: relu_t ---")
let t_relu = zeros(2, 2)
tset(t_relu, 0, 0,  1.0)
tset(t_relu, 0, 1, -0.5)
let r_relu = relu_t(t_relu)
print("relu(1.0):",  tget(r_relu, 0, 0))   // 1.0
print("relu(-0.5):", tget(r_relu, 0, 1))   // 0.0

print("--- test: gelu_t ---")
let t_gelu = zeros(1, 1)
let r_gelu = gelu_t(t_gelu)
print("gelu(0) ~0:", tget(r_gelu, 0, 0))   // ~0.0

print("--- test: softmax_2d ---")
let t_sm = ones(1, 3)
let r_sm = softmax_2d(t_sm)
let sm_sum = tget(r_sm, 0, 0) + tget(r_sm, 0, 1) + tget(r_sm, 0, 2)
print("softmax sum ~1:", sm_sum)            // ~1.0
print("softmax each ~0.333:", tget(r_sm, 0, 0))

print("--- test: transpose_2d ---")
let t_tr = zeros(2, 3)
tset(t_tr, 0, 0, 1.0)
tset(t_tr, 0, 1, 2.0)
tset(t_tr, 1, 0, 3.0)
let t_tr_T = transpose_2d(t_tr)
print("T[0,0]:", tget(t_tr_T, 0, 0))   // 1.0
print("T[1,0]:", tget(t_tr_T, 1, 0))   // 2.0
print("T[0,1]:", tget(t_tr_T, 0, 1))   // 3.0

print("--- test: linear_forward ---")
// W=[2,3], b=[2], x=[2,3] → y=[2,2]
let W = randn(2, 3)
let b = zeros(1, 2)
let x = ones(2, 3)
let y = linear_forward(W, b, x)
print("linear out shape[0]:", y.shape[0])  // 2
print("linear out shape[1]:", y.shape[1])  // 2

print("--- test: layer_norm ---")
let xln = zeros(1, 2)
tset(xln, 0, 0, 1.0)
tset(xln, 0, 1, 3.0)
let gamma = ones(1, 2)
let beta  = zeros(1, 2)
let xln_out = layer_norm(xln, gamma, beta, 0.00001)
// mean=2, std=1 → [-1, 1]
print("ln[0,0] ~-1:", tget(xln_out, 0, 0))
print("ln[0,1] ~ 1:", tget(xln_out, 0, 1))

print("=== 모든 nn 테스트 완료 ===")

