// FreeLang GPT: attention.fl → attention.fl8
// Scaled Dot-Product Attention + Causal Mask + Multi-Head (simplified 2D)

print("=== Attention Module (attention.fl8) ===")

// ──────────────────────────────────────────────────────────
// 유틸 (nn.fl8에서 가져온 함수들)
// ──────────────────────────────────────────────────────────

fn transpose_2d(t: any) -> any {
  let rows = t.shape[0]
  let cols = t.shape[1]
  let out = zeros(cols, rows)
  let i = 0
  while i < rows {
    let j = 0
    while j < cols {
      tset(out, j, i, tget(t, i, j))
      j = j + 1
    }
    i = i + 1
  }
  return out
}

fn softmax_2d(t: any) -> any {
  let rows = t.shape[0]
  let cols = t.shape[1]
  let out = zeros(rows, cols)
  let i = 0
  while i < rows {
    let max_v = tget(t, i, 0)
    let k = 1
    while k < cols {
      let v = tget(t, i, k)
      if v > max_v { max_v = v }
      k = k + 1
    }
    let sum_e = 0.0
    let j = 0
    while j < cols {
      let e = exp(tget(t, i, j) - max_v)
      tset(out, i, j, e)
      sum_e = sum_e + e
      j = j + 1
    }
    let j2 = 0
    while j2 < cols {
      tset(out, i, j2, tget(out, i, j2) / sum_e)
      j2 = j2 + 1
    }
    i = i + 1
  }
  return out
}

fn tensor_add_2d(a: any, b: any) -> any {
  let size = len(a.data)
  let out = []
  let i = 0
  while i < size {
    push(out, a.data[i] + b.data[i])
    i = i + 1
  }
  return tensor(out, a.shape)
}

fn tensor_scale_2d(t: any, s: f64) -> any {
  let size = len(t.data)
  let out = []
  let i = 0
  while i < size {
    push(out, t.data[i] * s)
    i = i + 1
  }
  return tensor(out, t.shape)
}

fn linear_fwd(w: any, b: any, x: any) -> any {
  let wt = transpose(w)
  let out = matmul(x, wt)
  let rows = out.shape[0]
  let cols = out.shape[1]
  let i = 0
  while i < rows {
    let j = 0
    while j < cols {
      tset(out, i, j, tget(out, i, j) + b.data[j])
      j = j + 1
    }
    i = i + 1
  }
  return out
}

// ──────────────────────────────────────────────────────────
// 1. Causal mask
// ──────────────────────────────────────────────────────────

fn make_causal_mask(seq_len: i64) -> any {
  let mask = zeros(seq_len, seq_len)
  let i = 0
  while i < seq_len {
    let j = 0
    while j < seq_len {
      if j > i {
        tset(mask, i, j, -9999.0)
      }
      j = j + 1
    }
    i = i + 1
  }
  return mask
}

// ──────────────────────────────────────────────────────────
// 2. Scaled dot-product attention (2D: seq_len × d_k)
// ──────────────────────────────────────────────────────────

fn scaled_dot_product(q: any, k: any, v: any, d_k: f64, use_mask: bool) -> any {
  // scores = Q @ K^T / sqrt(d_k)
  let kt = transpose_2d(k)
  let scores = matmul(q, kt)
  let scale = 1.0 / sqrt(d_k)
  let scaled = tensor_scale_2d(scores, scale)

  // optional causal mask
  let masked = scaled
  if use_mask {
    let seq_len = q.shape[0]
    let m = make_causal_mask(seq_len)
    masked = tensor_add_2d(scaled, m)
  }

  // softmax → attn weights
  let attn = softmax_2d(masked)

  // output = attn @ V
  return matmul(attn, v)
}

// ──────────────────────────────────────────────────────────
// 3. Single-head attention forward
// ──────────────────────────────────────────────────────────

fn attention_forward(wq: any, wk: any, wv: any, wo: any,
                     bq: any, bk: any, bv: any, bo: any,
                     x: any, use_mask: bool) -> any {
  let d_model = x.shape[1]
  let q = linear_fwd(wq, bq, x)
  let k = linear_fwd(wk, bk, x)
  let v = linear_fwd(wv, bv, x)
  let attn_out = scaled_dot_product(q, k, v, float(d_model), use_mask)
  return linear_fwd(wo, bo, attn_out)
}

// ──────────────────────────────────────────────────────────
// 4. 테스트
// ──────────────────────────────────────────────────────────

print("--- test: causal mask 3x3 ---")
let mask = make_causal_mask(3)
print("mask[0,0]:", tget(mask, 0, 0))    //  0
print("mask[0,1]:", tget(mask, 0, 1))    // -9999
print("mask[1,0]:", tget(mask, 1, 0))    //  0
print("mask[2,2]:", tget(mask, 2, 2))    //  0

print("--- test: scaled_dot_product (no mask) ---")
let seq = 4
let d_k = 8
let q = ones(seq, d_k)
let k = ones(seq, d_k)
let v = ones(seq, d_k)
let out = scaled_dot_product(q, k, v, float(d_k), false)
print("out shape[0]:", out.shape[0])   // 4
print("out shape[1]:", out.shape[1])   // 8
// 모든 attn weight 동일 → 출력도 ones
print("out[0,0] ~1:", out.data[0])

print("--- test: scaled_dot_product (causal mask) ---")
let out_c = scaled_dot_product(q, k, v, float(d_k), true)
print("out_c shape[0]:", out_c.shape[0])   // 4
print("out_c shape[1]:", out_c.shape[1])   // 8

print("--- test: attention_forward ---")
let d = 8
let wq = randn(d, d)
let wk = randn(d, d)
let wv = randn(d, d)
let wo = randn(d, d)
let bq = zeros(1, d)
let bk = zeros(1, d)
let bv = zeros(1, d)
let bo = zeros(1, d)
let x  = randn(4, d)

let y = attention_forward(wq, wk, wv, wo, bq, bk, bv, bo, x, false)
print("attn out shape[0]:", y.shape[0])   // 4
print("attn out shape[1]:", y.shape[1])   // 8

let y_c = attention_forward(wq, wk, wv, wo, bq, bk, bv, bo, x, true)
print("causal attn out shape[0]:", y_c.shape[0])  // 4
print("causal attn out shape[1]:", y_c.shape[1])  // 8

print("=== 모든 attention 테스트 완료 ===")

