  return tensor(out, a.shape)
}

fn tensor_scale_2d(t: any, s: f64) -> any {
  let n = len(t.data)
  let out = []
  let i = 0
  while i < n {
    push(out, t.data[i] * s)
    i = i + 1
  }
  return tensor(out, t.shape)
}

fn linear_fwd(w: any, b: any, x: any) -> any {
  let wt = transpose(w)
  let out = matmul(x, wt)
  let rows = out.shape[0]
  let cols = out.shape[1]
  let i = 0
  while i < rows {
    let j = 0
    while j < cols {
      tset(out, i, j, tget(out, i, j) + b.data[j])
      j = j + 1
    }
    i = i + 1
  }
  return out
}

fn layer_norm(x: any, gamma: any, beta: any, eps: f64) -> any {
  let rows = x.shape[0]
  let cols = x.shape[1]
  let out = zeros(rows, cols)
  let i = 0
  while i < rows {
    let sum = 0.0
    let j = 0
    while j < cols {
      sum = sum + tget(x, i, j)
      j = j + 1
    }
    let mean = sum / cols
    let vs = 0.0
    let j2 = 0
    while j2 < cols {
      let d = tget(x, i, j2) - mean
      vs = vs + d * d
      j2 = j2 + 1
    }
    let std = sqrt(vs / cols + eps)
    let j3 = 0
    while j3 < cols {
      tset(out, i, j3, (tget(x, i, j3) - mean) / std * gamma.data[j3] + beta.data[j3])
      j3 = j3 + 1
    }
    i = i + 1
  }
  return out
}

fn gelu_t(t: any) -> any {
  let cc = 0.7978845608028654
  let kc = 0.044715
  let n = len(t.data)
  let out = []
  let i = 0
  while i < n {
    let v = t.data[i]
    let cdf = 0.5 * (1.0 + tanh(cc * (v + kc * v * v * v)))
    push(out, v * cdf)
    i = i + 1
  }
  return tensor(out, t.shape)
}

fn make_causal_mask(seq_len: i64) -> any {
  let mask = zeros(seq_len, seq_len)
  let i = 0
  while i < seq_len {
    let j = 0
    while j < seq_len {
      if j > i { tset(mask, i, j, -9999.0) }
      j = j + 1
    }
    i = i + 1
  }
  return mask
}

fn scaled_dot_product(q: any, k: any, v: any, d_k: f64, use_mask: bool) -> any {
  let kt = transpose_2d(k)
  let scores = matmul(q, kt)
  let scaled = tensor_scale_2d(scores, 1.0 / sqrt(d_k))
  let masked = scaled
  if use_mask {
    let m = make_causal_mask(q.shape[0])
    masked = tensor_add_2d(scaled, m)
  }
  return matmul(softmax_2d(masked), v)
}

fn attn_fwd(wq: any, wk: any, wv: any, wo: any,
            bq: any, bk: any, bv: any, bo: any,
            x: any, use_mask: bool) -> any {
  let d = float(x.shape[1])
  let q = linear_fwd(wq, bq, x)
  let k = linear_fwd(wk, bk, x)
  let v = linear_fwd(wv, bv, x)
  return linear_fwd(wo, bo, scaled_dot_product(q, k, v, d, use_mask))
}

// ──────────────────────────────────────────────────────────
// 1. FFN
// ──────────────────────────────────────────────────────────

fn ffn_fwd(w1: any, b1: any, w2: any, b2: any, x: any) -> any {
  let h = gelu_t(linear_fwd(w1, b1, x))
  return linear_fwd(w2, b2, h)
}

// ──────────────────────────────────────────────────────────
// 2. Transformer Block (Pre-LN)
// x → LN → MHA → residual → LN → FFN → residual
// ──────────────────────────────────────────────────────────

fn block_fwd(wq: any, wk: any, wv: any, wo: any,
             bq: any, bk: any, bv: any, bo: any,
             ln1_g: any, ln1_b: any,
             w1: any, b1: any, w2: any, b2: any,
             ln2_g: any, ln2_b: any,
             x: any, use_mask: bool) -> any {
  // MHA branch
  let x_ln1 = layer_norm(x, ln1_g, ln1_b, 0.00001)
  let mha_out = attn_fwd(wq, wk, wv, wo, bq, bk, bv, bo, x_ln1, use_mask)
  let x1 = tensor_add_2d(x, mha_out)

  // FFN branch
  let x_ln2 = layer_norm(x1, ln2_g, ln2_b, 0.00001)
  let ffn_out = ffn_fwd(w1, b1, w2, b2, x_ln2)
  return tensor_add_2d(x1, ffn_out)
}

// ──────────────────────────────────────────────────────────
// 3. GPT forward (1 block, small config)
// token_ids → embed → block → LN → LM head
// ──────────────────────────────────────────────────────────

fn gpt_fwd(token_embed: any, pos_embed: any,
           wq: any, wk: any, wv: any, wo: any,
           bq: any, bk: any, bv: any, bo: any,
           ln1_g: any, ln1_b: any,
           w1: any, b1: any, w2: any, b2: any,
           ln2_g: any, ln2_b: any,
           lm_w: any, lm_b: any,
           ln_f_g: any, ln_f_b: any,
           token_ids: any) -> any {
  let seq_len = len(token_ids)
  let d_model = token_embed.shape[1]

  // token embedding lookup
  let x = zeros(seq_len, d_model)
  let i = 0
  while i < seq_len {
    let tok = int(token_ids[i])
    let j = 0
    while j < d_model {
      tset(x, i, j, tget(token_embed, tok, j) + tget(pos_embed, i, j))
      j = j + 1
    }
    i = i + 1
  }

  // transformer block
  let x1 = block_fwd(wq, wk, wv, wo, bq, bk, bv, bo,
                     ln1_g, ln1_b, w1, b1, w2, b2, ln2_g, ln2_b,
                     x, true)

  // final LN + LM head
  let x_norm = layer_norm(x1, ln_f_g, ln_f_b, 0.00001)
  return linear_fwd(lm_w, lm_b, x_norm)
}

// ──────────────────────────────────────────────────────────
// 4. 테스트
// ──────────────────────────────────────────────────────────

print("--- test: FFN forward ---")
let d = 8
let w1 = randn(d * 4, d)
let b1 = zeros(1, d * 4)
let w2 = randn(d, d * 4)
let b2 = zeros(1, d)
let x_ffn = ones(4, d)
let ffn_out = ffn_fwd(w1, b1, w2, b2, x_ffn)
print("ffn out shape[0]:", ffn_out.shape[0])   // 4
print("ffn out shape[1]:", ffn_out.shape[1])   // 8

print("--- test: TransformerBlock forward ---")
let wq = randn(d, d)
let wk = randn(d, d)
let wv = randn(d, d)
let wo = randn(d, d)
let bq = zeros(1, d)
let bk = zeros(1, d)
let bv = zeros(1, d)
let bo = zeros(1, d)
let ln1_g = ones(1, d)
let ln1_b = zeros(1, d)
let ln2_g = ones(1, d)
let ln2_b = zeros(1, d)
let x_blk = randn(4, d)

let blk_out = block_fwd(wq, wk, wv, wo, bq, bk, bv, bo,
                        ln1_g, ln1_b, w1, b1, w2, b2, ln2_g, ln2_b,
                        x_blk, true)
print("block out shape[0]:", blk_out.shape[0])  // 4
print("block out shape[1]:", blk_out.shape[1])  // 8

print("--- test: GPT forward ---")
let vocab_size = 20
let seq_len = 4
let token_embed = randn(vocab_size, d)
let pos_embed   = randn(seq_len, d)
let lm_w = randn(vocab_size, d)
let lm_b = zeros(1, vocab_size)
let ln_f_g = ones(1, d)
let ln_f_b = zeros(1, d)
let token_ids = [0, 1, 2, 3]

let logits = gpt_fwd(token_embed, pos_embed,
                     wq, wk, wv, wo, bq, bk, bv, bo,
                     ln1_g, ln1_b, w1, b1, w2, b2, ln2_g, ln2_b,
                     lm_w, lm_b, ln_f_g, ln_f_b,
                     token_ids)

print("logits shape[0]:", logits.shape[0])   // 4 (seq_len)
print("logits shape[1]:", logits.shape[1])   // 20 (vocab_size)

// 각 위치마다 softmax 합이 ~1인지 확인
let first_row_sm = softmax_2d(tensor([logits.data[0], logits.data[1], logits.data[2], logits.data[3]], [1, 4]))
print("logits row 0 is finite:", logits.data[0])

print("=== 모든 transformer 테스트 완료 ===")

