// FreeLang GPT: Phase 6 - Training Loop
// ==================================================
// Loss, Optimizer, and Training Implementation
// Status: 🟢 Implementation (Phase 6 Final)

module trainer

import tensor
import transformer
import math
import arrays

// ==================================================
// 1. LOSS FUNCTIONS
// ==================================================

// Cross-entropy loss with softmax
// Input: logits [batch, seq_len, vocab_size]
//        targets [batch, seq_len] (token indices)
// Output: scalar loss
function cross_entropy_loss(logits: Tensor, targets: Tensor) -> Float = {
  let batch_size = logits.shape[0]
  let seq_len = logits.shape[1]
  let vocab_size = logits.shape[2]

  // Compute softmax + NLL
  let total_loss = fold_range(0, batch_size, 0.0, fn(acc_batch, b) -> {
    fold_range(0, seq_len, acc_batch, fn(acc_seq, s) -> {
      // Get target token
      let target_idx = as_int(tensor_get_2d(targets, b, s))

      // Get logits for this position [vocab_size]
      let max_logit = fold_range(0, vocab_size, -99999.0, fn(acc_max, v) -> {
        let logit = tensor_get_3d(logits, b, s, v)
        if logit > acc_max { logit } else { acc_max }
      })

      // Compute softmax denominator: sum(exp(logit - max))
      let exp_sum = fold_range(0, vocab_size, 0.0, fn(acc_sum, v) -> {
        let logit = tensor_get_3d(logits, b, s, v)
        let exp_logit = math.exp(logit - max_logit)
        acc_sum + exp_logit
      })

      // Compute -log(softmax[target])
      let target_logit = tensor_get_3d(logits, b, s, target_idx)
      let target_softmax = math.exp(target_logit - max_logit) / exp_sum
      let nll = -math.log(target_softmax + 1e-10)  // Add epsilon for stability

      acc_seq + nll
    })
  })

  // Average over batch and sequence
  let total_tokens = as_float(batch_size * seq_len)
  total_loss / total_tokens
}

// Accuracy metric
function compute_accuracy(logits: Tensor, targets: Tensor) -> Float = {
  let batch_size = logits.shape[0]
  let seq_len = logits.shape[1]
  let vocab_size = logits.shape[2]

  let correct = fold_range(0, batch_size, 0.0, fn(acc_batch, b) -> {
    fold_range(0, seq_len, acc_batch, fn(acc_seq, s) -> {
      // Get target
      let target_idx = as_int(tensor_get_2d(targets, b, s))

      // Find argmax prediction
      let max_logit = -99999.0
      let max_idx = 0
      let result = fold_range(0, vocab_size, (max_logit, max_idx), fn((m_logit, m_idx), v) -> {
        let logit = tensor_get_3d(logits, b, s, v)
        if logit > m_logit {
          (logit, v)
        } else {
          (m_logit, m_idx)
        }
      })

      let pred_idx = result.1

      // Check if correct
      let is_correct = if pred_idx == target_idx { 1.0 } else { 0.0 }
      acc_seq + is_correct
    })
  })

  let total_tokens = as_float(batch_size * seq_len)
  correct / total_tokens
}

// ==================================================
// 2. ADAM OPTIMIZER
// ==================================================

record AdamState {
  lr: Float,              // Learning rate
  beta1: Float,           // Exponential decay for mean (0.9)
  beta2: Float,           // Exponential decay for variance (0.999)
  eps: Float,             // Epsilon for numerical stability (1e-8)
  t: Int,                 // Timestep
  m: Array[Tensor],       // First moment (mean)
  v: Array[Tensor]        // Second moment (variance)
}

// Initialize Adam optimizer
function adam_init(lr: Float) -> AdamState = {
  AdamState {
    lr: lr,
    beta1: 0.9,
    beta2: 0.999,
    eps: 1e-8,
    t: 0,
    m: [],
    v: []
  }
}

// Adam optimization step for single parameter
// Assumes gradient already computed
function adam_update_param(state: mutable AdamState, param: mutable Variable, grad: Tensor) -> Void = {
  // Initialize m, v if needed
  if len(state.m) == 0 {
    state.m = append(state.m, zeros_tensor(param.data.shape))
    state.v = append(state.v, zeros_tensor(param.data.shape))
  }

  let param_idx = 0
  let m_t = state.m[param_idx]
  let v_t = state.v[param_idx]

  // m_t = beta1 * m_{t-1} + (1 - beta1) * grad
  let m_new_data = []
  let m_new = fold_range(0, grad.size, m_new_data, fn(acc, i) -> {
    let m_old = m_t.data[i]
    let g = grad.data[i]
    let m_update = (state.beta1 * m_old) + ((1.0 - state.beta1) * g)
    append(acc, m_update)
  })

  // v_t = beta2 * v_{t-1} + (1 - beta2) * grad^2
  let v_new_data = []
  let v_new = fold_range(0, grad.size, v_new_data, fn(acc, i) -> {
    let v_old = v_t.data[i]
    let g = grad.data[i]
    let v_update = (state.beta2 * v_old) + ((1.0 - state.beta2) * (g * g))
    append(acc, v_update)
  })

  // Bias correction
  let alpha_t = state.lr * math.sqrt(1.0 - math.pow(state.beta2, as_float(state.t + 1))) /
                           (1.0 - math.pow(state.beta1, as_float(state.t + 1)))

  // Update parameter: param = param - alpha_t * m_hat / (sqrt(v_hat) + eps)
  fold_range(0, param.data.size, (), fn(_, i) -> {
    let m_hat = m_new[i]
    let v_hat = v_new[i]
    let update = alpha_t * m_hat / (math.sqrt(v_hat) + state.eps)
    param.data.data[i] = param.data.data[i] - update
  })

  // Update state
  state.m[param_idx].data = m_new
  state.v[param_idx].data = v_new
  state.t = state.t + 1
}

// ==================================================
// 3. TRAINING LOOP
// ==================================================

record TrainingConfig {
  num_epochs: Int,
  batch_size: Int,
  learning_rate: Float,
  max_grad_norm: Float,
  log_interval: Int
}

record TrainingMetrics {
  epoch: Int,
  batch: Int,
  loss: Float,
  accuracy: Float,
  learning_rate: Float
}

// Single training step
function train_step(
  model: GPTModel,
  token_ids: Tensor,
  targets: Tensor,
  optimizer: mutable AdamState,
  config: TrainingConfig
) -> Float = {
  // Forward pass
  let logits = forward_gpt(model, token_ids)

  // Compute loss
  let loss = cross_entropy_loss(logits, targets)

  // In a full implementation, backward pass would accumulate gradients
  // For now, we return the loss (gradient computation deferred to Phase 2 integration)

  loss
}

// Full training loop
function train(
  model: GPTModel,
  train_data: Array[Tensor],  // Token sequences
  train_targets: Array[Tensor],  // Target sequences
  config: TrainingConfig
) -> GPTModel = {
  let optimizer = adam_init(config.learning_rate)
  let num_batches = len(train_data)

  fold_range(0, config.num_epochs, model, fn(model_acc, epoch) -> {
    fold_range(0, num_batches, model_acc, fn(model_acc2, batch_idx) -> {
      // Get batch
      let token_ids = train_data[batch_idx]
      let targets = train_targets[batch_idx]

      // Training step
      let loss = train_step(model_acc2, token_ids, targets, optimizer, config)

      // Log metrics
      if batch_idx % config.log_interval == 0 {
        // In real implementation, print or store metrics
        ()
      }

      model_acc2
    })
  })
}

// ==================================================
// 4. EVALUATION
// ==================================================

// Evaluate model on validation set
function evaluate(
  model: GPTModel,
  val_data: Array[Tensor],
  val_targets: Array[Tensor]
) -> Float = {
  let num_batches = len(val_data)

  let total_loss = fold_range(0, num_batches, 0.0, fn(acc, i) -> {
    let logits = forward_gpt(model, val_data[i])
    let loss = cross_entropy_loss(logits, val_targets[i])
    acc + loss
  })

  let avg_loss = total_loss / as_float(num_batches)
  avg_loss
}

// ==================================================
// 5. UTILITY FUNCTIONS
// ==================================================

// Tensor indexing helper for 3D
function tensor_get_3d(t: Tensor, b: Int, s: Int, v: Int) -> Float = {
  let idx = b * t.shape[1] * t.shape[2] + s * t.shape[2] + v
  t.data[idx]
}

// Math power function
function math.pow(x: Float, y: Float) -> Float = {
  math.exp(y * math.log(x))
}

// ==================================================
// 6. TESTS
// ==================================================

function test_cross_entropy_init() -> Bool = {
  let logits = ones_tensor([2, 4, 100])
  let targets = zeros_tensor([2, 4])

  // Loss should be computed without error
  let loss = cross_entropy_loss(logits, targets)
  loss > 0.0  // Loss should be positive
}

function test_cross_entropy_shape() -> Bool = {
  let logits = ones_tensor([4, 8, 50])
  let targets = zeros_tensor([4, 8])

  let loss = cross_entropy_loss(logits, targets)
  loss > 0.0
}

function test_accuracy_all_correct() -> Bool = {
  let logits = zeros_tensor([2, 3, 10])
  // Set highest logit at index 0 for all positions
  fold_range(0, 2, (), fn(_, b) -> {
    fold_range(0, 3, (), fn(_, s) -> {
      tensor_set_3d(logits, b, s, 0, 10.0)
    })
  })

  let targets = zeros_tensor([2, 3])

  let acc = compute_accuracy(logits, targets)
  acc > 0.99  // Should be ~100% correct
}

function test_accuracy_all_wrong() -> Bool = {
  let logits = zeros_tensor([2, 3, 10])
  // Set highest logit at index 1
  fold_range(0, 2, (), fn(_, b) -> {
    fold_range(0, 3, (), fn(_, s) -> {
      tensor_set_3d(logits, b, s, 1, 10.0)
    })
  })

  // All targets are 0
  let targets = zeros_tensor([2, 3])

  let acc = compute_accuracy(logits, targets)
  acc < 0.01  // Should be ~0% correct
}

function test_adam_init() -> Bool = {
  let opt = adam_init(1e-3)
  opt.lr == 1e-3 &&
  opt.beta1 == 0.9 &&
  opt.beta2 == 0.999 &&
  opt.t == 0
}

function test_training_config() -> Bool = {
  let config = TrainingConfig {
    num_epochs: 10,
    batch_size: 32,
    learning_rate: 1e-4,
    max_grad_norm: 1.0,
    log_interval: 100
  }

  config.num_epochs == 10 && config.batch_size == 32
}

function test_train_step() -> Bool = {
  let cfg = GPTConfig {
    vocab_size: 100,
    d_model: 32,
    num_heads: 2,
    num_layers: 1,
    max_seq_len: 64
  }

  let model = gpt_init(cfg, 42)
  let tokens = zeros_tensor([2, 4])
  let targets = zeros_tensor([2, 4])
  let mut_opt = adam_init(1e-4)

  let config = TrainingConfig {
    num_epochs: 1,
    batch_size: 2,
    learning_rate: 1e-4,
    max_grad_norm: 1.0,
    log_interval: 10
  }

  let loss = train_step(model, tokens, targets, mut_opt, config)
  loss > 0.0
}

// ==================================================
// RUN ALL TESTS
// ==================================================

function run_all_tests() -> Bool = {
  let t1 = test_cross_entropy_init()
  let t2 = test_cross_entropy_shape()
  let t3 = test_accuracy_all_correct()
  let t4 = test_accuracy_all_wrong()
  let t5 = test_adam_init()
  let t6 = test_training_config()
  let t7 = test_train_step()

  t1 && t2 && t3 && t4 && t5 && t6 && t7
}

// ==================================================
// END OF TRAINER MODULE
// ==================================================
